203: 	since := header.Started
204: 	until := header.Ended
205: 	if until.IsZero() {
206: 		until = time.Now().UTC()
207: 	}
208: 
209: 	// 3. Query git log
210: 	logCommits, err := l.queryGitLog(repoRoot, branch, since, until)
211: 	if err != nil {
212: 		if isNoCommitsError(err) {
213: 			return nil, nil
214: 		}
215: 		if isNotGitRepoError(err) {
216: 			return nil, fmt.Errorf("%w: %s", ErrNotGitRepository, repoRoot)
217: 		}
218: 		return nil, fmt.Errorf("querying git log for branch %s: %w", branch, err)
219: 	}
220: 
221: 	// 4. Query git reflog
222: 	reflogCommits, _ := l.queryGitReflog(repoRoot, branch, since, until)
223: 
224: 	// Combine and deduplicate candidates by Hash
225: 	var candidates []CandidateCommit
226: 	seen := make(map[string]bool)
227: 	for _, c := range logCommits {
228: 		if !seen[c.Hash] {
229: 			seen[c.Hash] = true
230: 			candidates = append(candidates, c)
231: 		}
232: 	}
233: 	for _, c := range reflogCommits {
234: 		if !seen[c.Hash] {
235: 			seen[c.Hash] = true
236: 			candidates = append(candidates, c)
237: 		}
238: 	}
239: 
240: 	if len(candidates) == 0 {
241: 		return nil, nil
242: 	}
