258: 	// If timestamps match (e.g. commits made within the same second), preserve chronological git order.
259: 	sort.SliceStable(confirmed, func(i, j int) bool {
260: 		if !confirmed[i].Timestamp.Equal(confirmed[j].Timestamp) {
261: 			return confirmed[i].Timestamp.Before(confirmed[j].Timestamp)
262: 		}
263: 		return confirmed[i].Order < confirmed[j].Order
