package ops

import (
	"errors"
	"fmt"
	"strings"
)

// ValidateOp validates a single Op according to its OpType rules.
func ValidateOp(op Op) error {
	switch op.Type {
	case OpAdd:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("entry_id is required for add op")
		}
		if strings.TrimSpace(op.DossierScope) == "" {
			return errors.New("dossier_scope is required for add op")
		}
		if op.Fields == nil {
			return errors.New("fields is required for add op")
		}
		if err := requireStringField(op.Fields, "text", "add"); err != nil {
			return err
		}

	case OpAmend:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("entry_id is required for amend op")
		}
		if op.Fields == nil || len(op.Fields) == 0 {
			return errors.New("fields is required for amend op")
		}

	case OpSupersede:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("entry_id is required for supersede op")
		}
		if op.Fields == nil {
			return errors.New("fields is required for supersede op")
		}
		if err := requireStringField(op.Fields, "new_entry_id", "supersede"); err != nil {
			return err
		}
		if err := requireStringField(op.Fields, "text", "supersede"); err != nil {
			return err
		}

	case OpRetire:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("entry_id is required for retire op")
		}
		if op.Fields == nil {
			return errors.New("fields is required for retire op")
		}
		if err := requireStringField(op.Fields, "reason", "retire"); err != nil {
			return err
		}

	case OpMove:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("entry_id is required for move op")
		}
		if op.Fields == nil {
			return errors.New("fields is required for move op")
		}
		if err := requireStringField(op.Fields, "to_dossier", "move"); err != nil {
			return err
		}

	case OpSplit:
		if strings.TrimSpace(op.DossierScope) == "" {
			return errors.New("dossier_scope is required for split op")
		}
		if op.Fields == nil {
			return errors.New("fields is required for split op")
		}
		if err := validateNewDossiers(op.Fields); err != nil {
			return err
		}
		if err := validateEntryMoves(op.Fields); err != nil {
			return err
		}

	default:
		return fmt.Errorf("invalid op type: %q", op.Type)
	}

	return nil
}

// ValidateBatch validates all fields and operations in an OpBatch.
func ValidateBatch(batch OpBatch) error {
	if batch.Version <= 0 {
		return errors.New("batch version must be >= 1")
	}
	if strings.TrimSpace(batch.BatchID) == "" {
		return errors.New("batch_id is required")
	}
	if batch.CreatedAt.IsZero() {
		return errors.New("created_at is required")
	}
	if len(batch.Ops) == 0 {
		return errors.New("batch must contain at least one operation")
	}
	for i, op := range batch.Ops {
		if err := ValidateOp(op); err != nil {
			return fmt.Errorf("invalid op at index %d: %w", i, err)
		}
	}
	return nil
}

func requireStringField(fields map[string]any, key, opName string) error {
	v, ok := fields[key]
	if !ok {
		return fmt.Errorf("fields.%s is required for %s op", key, opName)
	}
	s, ok := v.(string)
	if !ok || strings.TrimSpace(s) == "" {
		return fmt.Errorf("fields.%s must be a non-empty string for %s op", key, opName)
	}
	return nil
}

func validateNewDossiers(fields map[string]any) error {
	v, ok := fields["new_dossiers"]
	if !ok {
		return errors.New("fields.new_dossiers is required for split op")
	}

	switch list := v.(type) {
	case []string:
		if len(list) == 0 {
			return errors.New("fields.new_dossiers must contain at least one dossier scope")
		}
		for _, s := range list {
			if strings.TrimSpace(s) == "" {
				return errors.New("fields.new_dossiers contains an empty dossier scope")
			}
		}
	case []any:
		if len(list) == 0 {
			return errors.New("fields.new_dossiers must contain at least one dossier scope")
		}
		for _, elem := range list {
			s, ok := elem.(string)
			if !ok || strings.TrimSpace(s) == "" {
				return errors.New("fields.new_dossiers elements must be non-empty strings")
			}
		}
	default:
		return errors.New("fields.new_dossiers must be a list of strings")
	}
	return nil
}

func validateEntryMoves(fields map[string]any) error {
	v, ok := fields["entry_moves"]
	if !ok {
		return errors.New("fields.entry_moves is required for split op")
	}

	switch m := v.(type) {
	case map[string]string:
		if len(m) == 0 {
			return errors.New("fields.entry_moves must contain at least one entry move")
		}
		for k, s := range m {
			if strings.TrimSpace(k) == "" || strings.TrimSpace(s) == "" {
				return errors.New("fields.entry_moves contains empty entry ID or target scope")
			}
		}
	case map[string]any:
		if len(m) == 0 {
			return errors.New("fields.entry_moves must contain at least one entry move")
		}
		for k, elem := range m {
			s, ok := elem.(string)
			if !ok || strings.TrimSpace(k) == "" || strings.TrimSpace(s) == "" {
				return errors.New("fields.entry_moves values must be non-empty strings")
			}
		}
	default:
		return errors.New("fields.entry_moves must be a map of entry ID to dossier scope")
	}
	return nil
}

package ops

import (
	"crypto/rand"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/oklog/ulid/v2"
)

// Writer writes append-only OpBatch files to disk.
type Writer struct {
	baseDir string
	mu      sync.Mutex
}

// NewWriter creates a new Writer rooted at baseDir (typically .memory/ops).
func NewWriter(baseDir string) *Writer {
	return &Writer{
		baseDir: baseDir,
	}
}

// Write writes an OpBatch to disk as indented JSON under .memory/ops/<yyyy-mm>/<batch-id>.json.
func (w *Writer) Write(batch OpBatch) error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if batch.Version == 0 {
		batch.Version = 1
	}
	if batch.CreatedAt.IsZero() {
		if batch.BatchID != "" {
			if u, err := ulid.Parse(batch.BatchID); err == nil {
				batch.CreatedAt = time.UnixMilli(int64(u.Time())).UTC()
			}
		}
		if batch.CreatedAt.IsZero() {
			batch.CreatedAt = time.Now().UTC()
		}
	}

	// Normalize timestamps to strip monotonic clock readings
	batch.CreatedAt = batch.CreatedAt.UTC().Round(0)
	for i := range batch.Ops {
		if !batch.Ops[i].Timestamp.IsZero() {
			batch.Ops[i].Timestamp = batch.Ops[i].Timestamp.UTC().Round(0)
		}
	}

	if strings.TrimSpace(batch.BatchID) == "" {
		entropy := ulid.Monotonic(rand.Reader, 0)
		batch.BatchID = ulid.MustNew(ulid.Timestamp(batch.CreatedAt), entropy).String()
	}

	if err := ValidateBatch(batch); err != nil {
		return fmt.Errorf("validating batch: %w", err)
	}

	monthDir := batch.CreatedAt.UTC().Format("2006-01")
	dirPath := filepath.Join(w.baseDir, monthDir)
	if err := os.MkdirAll(dirPath, 0755); err != nil {
		return fmt.Errorf("creating directory %s: %w", dirPath, err)
	}

	cleanBatchID := strings.TrimSuffix(batch.BatchID, ".json")
	filePath := filepath.Join(dirPath, cleanBatchID+".json")

	data, err := json.MarshalIndent(batch, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling batch: %w", err)
	}
	data = append(data, '\n')

	// Atomically write the file
	tmpFile, err := os.CreateTemp(dirPath, "tmp-*.json")
	if err != nil {
		return fmt.Errorf("creating temp file in %s: %w", dirPath, err)
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	if _, err := tmpFile.Write(data); err != nil {
		tmpFile.Close()
		return fmt.Errorf("writing batch JSON: %w", err)
	}
	if err := tmpFile.Close(); err != nil {
		return fmt.Errorf("closing temp batch file: %w", err)
	}

	if err := os.Rename(tmpPath, filePath); err != nil {
		return fmt.Errorf("renaming temp file to %s: %w", filePath, err)
	}

	return nil
}

package ops

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// Reader reads and validates OpBatch files from disk.
type Reader struct {
	baseDir            string
	commitTimeResolver func(ctx context.Context, commit string) (time.Time, error)
}

// NewReader creates a new Reader rooted at baseDir (typically .memory/ops).
func NewReader(baseDir string) *Reader {
	return &Reader{
		baseDir: baseDir,
	}
}

// SetCommitTimeResolver overrides git commit timestamp resolution (primarily for testing).
func (r *Reader) SetCommitTimeResolver(resolver func(ctx context.Context, commit string) (time.Time, error)) {
	r.commitTimeResolver = resolver
}

// ReadBatch reads and validates a single batch file from path.
// The path may be absolute or relative to baseDir.
func (r *Reader) ReadBatch(path string) (*OpBatch, error) {
	targetPath := path
	if !filepath.IsAbs(targetPath) {
		candidate := filepath.Join(r.baseDir, path)
		if _, err := os.Stat(candidate); err == nil {
			targetPath = candidate
		} else if _, err := os.Stat(path); err == nil {
			targetPath = path
		} else {
			targetPath = candidate
		}
	}

	data, err := os.ReadFile(targetPath)
	if err != nil {
		return nil, fmt.Errorf("reading batch file: %w", err)
	}

	var batch OpBatch
	if err := json.Unmarshal(data, &batch); err != nil {
		return nil, fmt.Errorf("unmarshaling batch JSON from %s: %w", targetPath, err)
	}

	batch.CreatedAt = batch.CreatedAt.UTC().Round(0)
	for i := range batch.Ops {
		if !batch.Ops[i].Timestamp.IsZero() {
			batch.Ops[i].Timestamp = batch.Ops[i].Timestamp.UTC().Round(0)
		}
	}

	if err := ValidateBatch(batch); err != nil {
		return nil, fmt.Errorf("validating batch from %s: %w", targetPath, err)
	}

	return &batch, nil
}

