	"strings"
	"time"

	"github.com/oklog/ulid/v2"
)

// Iterator iterates over all op batches in chronological order.
type Iterator struct {
	reader *Reader
}

// NewIterator creates a new Iterator wrapping reader.
func NewIterator(r *Reader) *Iterator {
	return &Iterator{reader: r}
}

// All yields all batches in chronological order.
func (it *Iterator) All(ctx context.Context) iter.Seq2[*OpBatch, error] {
	return it.reader.Iterate(ctx)
}

// After yields only batches after the given batch ID.
func (it *Iterator) After(ctx context.Context, afterBatchID string) iter.Seq2[*OpBatch, error] {
	return it.reader.IterateAfter(ctx, afterBatchID)
}

// Before yields only batches whose CreatedAt is before the commit's timestamp.
func (it *Iterator) Before(ctx context.Context, beforeCommit string) iter.Seq2[*OpBatch, error] {
	return it.reader.IterateBefore(ctx, beforeCommit)
}

// Iterate yields batches in ULID order (which is chronological).
// It walks month directories in order, then batch files within each month in ULID order.
func (r *Reader) Iterate(ctx context.Context) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		if _, err := os.Stat(r.baseDir); err != nil {
			if os.IsNotExist(err) {
				return
			}
			yield(nil, fmt.Errorf("stat base dir: %w", err))
			return
		}

		entries, err := os.ReadDir(r.baseDir)
		if err != nil {
			yield(nil, fmt.Errorf("reading base dir: %w", err))
			return
		}

		var monthDirs []string
		for _, entry := range entries {
			if entry.IsDir() && isMonthDir(entry.Name()) {
				monthDirs = append(monthDirs, entry.Name())
			}
		}
		sort.Strings(monthDirs)

		for _, month := range monthDirs {
			monthPath := filepath.Join(r.baseDir, month)
			files, err := os.ReadDir(monthPath)
			if err != nil {
				yield(nil, fmt.Errorf("reading month dir %s: %w", month, err))
				return
			}

			var jsonFiles []string
			for _, file := range files {
				if !file.IsDir() && strings.HasSuffix(file.Name(), ".json") {
					jsonFiles = append(jsonFiles, file.Name())
				}
			}
			sort.Strings(jsonFiles)

			for _, fileName := range jsonFiles {
				if err := ctx.Err(); err != nil {
					yield(nil, err)
					return
				}

				filePath := filepath.Join(monthPath, fileName)
				batch, err := r.ReadBatch(filePath)
				if err != nil {
					if !yield(nil, fmt.Errorf("reading batch %s: %w", filePath, err)) {
						return
					}
					continue
				}

				if !yield(batch, nil) {
					return
				}
			}
		}
	}
}

// IterateAfter yields only batches after the given batch ID (for incremental processing).
func (r *Reader) IterateAfter(ctx context.Context, afterBatchID string) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		if afterBatchID == "" {
			for batch, err := range r.Iterate(ctx) {
				if !yield(batch, err) {
					return
				}
			}
			return
		}

		cleanAfterID := strings.TrimSuffix(afterBatchID, ".json")
		parsedAfter, errAfter := ulid.Parse(cleanAfterID)

		seen := false
		for batch, err := range r.Iterate(ctx) {
			if err != nil {
				if !yield(nil, err) {
					return
				}
				continue
			}

			if !seen {
				if batch.BatchID == cleanAfterID {
					seen = true
					continue
				}
				if errAfter == nil {
					if parsedBatch, errBatch := ulid.Parse(batch.BatchID); errBatch == nil {
						if parsedBatch.Compare(parsedAfter) > 0 {
							seen = true
							if !yield(batch, nil) {
								return
							}
							continue
						}
					}
				}
				continue
			}

			if !yield(batch, nil) {
				return
			}
		}
	}
}

// IterateBefore yields only batches whose CreatedAt is before the given commit's timestamp.
// Resolves commit timestamp via `git log -1 --format=%cI <commit>`.
func (r *Reader) IterateBefore(ctx context.Context, beforeCommit string) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		cutoff, err := r.resolveCommitTimestamp(ctx, beforeCommit)
		if err != nil {
			yield(nil, err)
			return
		}

		for batch, err := range r.Iterate(ctx) {
			if err != nil {
				if !yield(nil, err) {
					return
				}
				continue
			}

			if batch.CreatedAt.Before(cutoff) {
				if !yield(batch, nil) {
					return
				}
			}
		}
	}
}

func (r *Reader) resolveCommitTimestamp(ctx context.Context, commit string) (time.Time, error) {
	if r.commitTimeResolver != nil {
		return r.commitTimeResolver(ctx, commit)
	}

	if strings.TrimSpace(commit) == "" {
		return time.Time{}, errors.New("beforeCommit must not be empty")
	}

	var cmd *exec.Cmd
	if r.baseDir != "" {
		cmd = exec.CommandContext(ctx, "git", "-C", r.baseDir, "log", "-1", "--format=%cI", commit)
	} else {
		cmd = exec.CommandContext(ctx, "git", "log", "-1", "--format=%cI", commit)
	}

	out, err := cmd.CombinedOutput()
	if err != nil {
		fallbackCmd := exec.CommandContext(ctx, "git", "log", "-1", "--format=%cI", commit)
		fbOut, fbErr := fallbackCmd.CombinedOutput()
		if fbErr != nil {
			return time.Time{}, fmt.Errorf("resolving git commit %s timestamp: %w (output: %s)", commit, err, strings.TrimSpace(string(out)))
		}
		out = fbOut
	}

	str := strings.TrimSpace(string(out))
	if str == "" {
		return time.Time{}, fmt.Errorf("empty timestamp output for commit %s", commit)
	}

	t, err := time.Parse(time.RFC3339, str)
	if err != nil {
		t, err = time.Parse(time.RFC3339Nano, str)
		if err != nil {
			return time.Time{}, fmt.Errorf("parsing commit timestamp %q: %w", str, err)
		}
	}

	return t, nil
}

func isMonthDir(name string) bool {
	if len(name) != 7 || name[4] != '-' {
		return false
	}
	for i := 0; i < 7; i++ {
		if i == 4 {
			continue
		}
		if name[i] < '0' || name[i] > '9' {
			return false
		}
	}
	return true
}

package ops

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// MigrateV1Events moves eventsDir to archiveDir if eventsDir exists.
// This archives legacy v1 events (.memory/events/) to .memory/archive/v1-events/.
func MigrateV1Events(eventsDir, archiveDir string) error {
	info, err := os.Stat(eventsDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("stat events directory %s: %w", eventsDir, err)
	}

	if !info.IsDir() {
		return fmt.Errorf("events path %s is not a directory", eventsDir)
	}

	if err := os.MkdirAll(filepath.Dir(archiveDir), 0755); err != nil {
		return fmt.Errorf("creating archive parent directory: %w", err)
	}

	// Try atomic rename first
	if err := os.Rename(eventsDir, archiveDir); err == nil {
		return nil
	}

	// Fallback if rename fails (e.g. cross-device link or existing target dir): copy and remove
	if err := copyDirectory(eventsDir, archiveDir); err != nil {
		return fmt.Errorf("copying events directory to archive: %w", err)
	}

	if err := os.RemoveAll(eventsDir); err != nil {
		return fmt.Errorf("removing legacy events directory: %w", err)
	}

	return nil
}

func copyDirectory(src, dst string) error {
	if err := os.MkdirAll(dst, 0755); err != nil {
		return err
	}
	entries, err := os.ReadDir(src)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		srcPath := filepath.Join(src, entry.Name())
		dstPath := filepath.Join(dst, entry.Name())
		if entry.IsDir() {
			if err := copyDirectory(srcPath, dstPath); err != nil {
				return err
			}
		} else {
			if err := copyFile(srcPath, dstPath); err != nil {
				return err
			}
		}
	}
	return nil
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	if _, err := io.Copy(out, in); err != nil {
		return err
	}
	return out.Close()
}

