func TestValidateBatch(t *testing.T) {
	validOp := ops.Op{
		Type:         ops.OpAdd,
		EntryID:      "inv-01J5K3M2",
		DossierScope: "core/test",
		Fields:       map[string]any{"text": "valid invariant"},
