				if tt.errSub != "" && !strings.Contains(err.Error(), tt.errSub) {
					t.Fatalf("expected error containing %q, got %q", tt.errSub, err.Error())
				}
			} else {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
			}
		})
	}
}

func TestWriterAndReaderRoundTrip(t *testing.T) {
	tmpDir := t.TempDir()
	w := ops.NewWriter(tmpDir)
	r := ops.NewReader(tmpDir)

	batchTime := time.Date(2026, 10, 10, 15, 30, 0, 0, time.UTC)
	batchID := "01J5K3M2ABCDEFGH1234567890"

	batch := ops.OpBatch{
		Version:   1,
		BatchID:   batchID,
		CreatedAt: batchTime,
		Ops: []ops.Op{
			{
				Type:         ops.OpAdd,
				EntryID:      "inv-01J5K3M2",
				DossierScope: "core/parser",
				Timestamp:    batchTime,
				Source:       "turn-note",
				SessionID:    "sess-123",
				Fields: map[string]any{
					"text":     "Parser must never return nil slice on empty input",
