				Timestamp: batchTime,
				Source:    "sidecar",
				Fields: map[string]any{
					"new_entry_id": "inv-01J5K3M3",
					"text":         "Parser emits an empty array token",
				},
			},
			{
				Type:      ops.OpRetire,
				EntryID:   "inv-01J5K3M2",
				Timestamp: batchTime,
				Source:    "pa",
				Fields: map[string]any{
					"reason": "Rule no longer applicable after refactor",
				},
			},
			{
				Type:      ops.OpMove,
				EntryID:   "inv-01J5K3M3",
				Timestamp: batchTime,
				Source:    "consolidation",
				Fields: map[string]any{
					"to_dossier": "core/tokens",
				},
			},
			{
				Type:         ops.OpSplit,
				DossierScope: "core/parser",
				Timestamp:    batchTime,
				Source:       "consolidation",
				Fields: map[string]any{
					"new_dossiers": []any{"core/parser-ast", "core/parser-tokens"},
					"entry_moves":  map[string]any{"inv-01J5K3M3": "core/parser-tokens"},
				},
			},
		},
	}

	if err := w.Write(batch); err != nil {
		t.Fatalf("Writer.Write failed: %v", err)
	}

	// Verify file was written to <yyyy-mm>/<batch-id>.json
	expectedPath := filepath.Join(tmpDir, "2026-10", batchID+".json")
	content, err := os.ReadFile(expectedPath)
	if err != nil {
		t.Fatalf("expected file to exist at %s: %v", expectedPath, err)
	}
	if !strings.HasPrefix(string(content), "{\n") {
		t.Fatalf("expected indented JSON, got: %s", string(content))
	}

	// Read via absolute path
	readBatch, err := r.ReadBatch(expectedPath)
	if err != nil {
		t.Fatalf("Reader.ReadBatch (absolute) failed: %v", err)
	}

	if readBatch.Version != batch.Version {
		t.Errorf("expected version %d, got %d", batch.Version, readBatch.Version)
	}
	if readBatch.BatchID != batch.BatchID {
		t.Errorf("expected batch ID %s, got %s", batch.BatchID, readBatch.BatchID)
	}
	if !readBatch.CreatedAt.Equal(batch.CreatedAt) {
		t.Errorf("expected created_at %v, got %v", batch.CreatedAt, readBatch.CreatedAt)
	}
	if len(readBatch.Ops) != len(batch.Ops) {
		t.Fatalf("expected %d ops, got %d", len(batch.Ops), len(readBatch.Ops))
	}

	for i, op := range readBatch.Ops {
		expectedOp := batch.Ops[i]
		if op.Type != expectedOp.Type {
			t.Errorf("op[%d] type mismatch: expected %s, got %s", i, expectedOp.Type, op.Type)
		}
		if op.EntryID != expectedOp.EntryID {
			t.Errorf("op[%d] entry_id mismatch: expected %s, got %s", i, expectedOp.EntryID, op.EntryID)
		}
		if op.DossierScope != expectedOp.DossierScope {
			t.Errorf("op[%d] dossier_scope mismatch: expected %s, got %s", i, expectedOp.DossierScope, op.DossierScope)
		}
	}

	// Read via relative path
	relPath := filepath.Join("2026-10", batchID+".json")
	readRel, err := r.ReadBatch(relPath)
	if err != nil {
		t.Fatalf("Reader.ReadBatch (relative) failed: %v", err)
	}
	if readRel.BatchID != batchID {
		t.Errorf("expected relative read batch ID %s, got %s", batchID, readRel.BatchID)
	}
}

func TestReaderIterate(t *testing.T) {
	tmpDir := t.TempDir()
	w := ops.NewWriter(tmpDir)
	r := ops.NewReader(tmpDir)

	// Create 3 batches across 2 months:
	// Month 1: 2026-08 (Batch 1)
	// Month 2: 2026-09 (Batch 2 and Batch 3)
	t1 := time.Date(2026, 8, 15, 10, 0, 0, 0, time.UTC)
	t2 := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)
	t3 := time.Date(2026, 9, 2, 10, 0, 0, 0, time.UTC)

	u1 := ulid.MustNew(ulid.Timestamp(t1), ulid.Monotonic(strings.NewReader("entropy1entropy1"), 0)).String()
	u2 := ulid.MustNew(ulid.Timestamp(t2), ulid.Monotonic(strings.NewReader("entropy2entropy2"), 0)).String()
	u3 := ulid.MustNew(ulid.Timestamp(t3), ulid.Monotonic(strings.NewReader("entropy3entropy3"), 0)).String()

	b1 := ops.OpBatch{
		Version:   1,
		BatchID:   u1,
		CreatedAt: t1,
		Ops: []ops.Op{
			{Type: ops.OpAdd, EntryID: "inv-01", DossierScope: "s1", Fields: map[string]any{"text": "t1"}},
		},
	}
	b2 := ops.OpBatch{
		Version:   1,
		BatchID:   u2,
		CreatedAt: t2,
		Ops: []ops.Op{
			{Type: ops.OpAdd, EntryID: "inv-02", DossierScope: "s1", Fields: map[string]any{"text": "t2"}},
		},
	}
	b3 := ops.OpBatch{
		Version:   1,
		BatchID:   u3,
		CreatedAt: t3,
		Ops: []ops.Op{
			{Type: ops.OpAdd, EntryID: "inv-03", DossierScope: "s1", Fields: map[string]any{"text": "t3"}},
		},
	}

	// Write out of order to ensure iterator sorts properly
	if err := w.Write(b2); err != nil {
		t.Fatalf("Write b2: %v", err)
	}
	if err := w.Write(b3); err != nil {
		t.Fatalf("Write b3: %v", err)
	}
	if err := w.Write(b1); err != nil {
		t.Fatalf("Write b1: %v", err)
	}

	var results []*ops.OpBatch
	for batch, err := range r.Iterate(context.Background()) {
		if err != nil {
			t.Fatalf("iteration error: %v", err)
		}
		results = append(results, batch)
	}

	if len(results) != 3 {
		t.Fatalf("expected 3 batches, got %d", len(results))
	}
	if results[0].BatchID != u1 {
		t.Errorf("expected 1st batch %s, got %s", u1, results[0].BatchID)
	}
	if results[1].BatchID != u2 {
		t.Errorf("expected 2nd batch %s, got %s", u2, results[1].BatchID)
	}
	if results[2].BatchID != u3 {
		t.Errorf("expected 3rd batch %s, got %s", u3, results[2].BatchID)
	}
}

func TestReaderIterateAfter(t *testing.T) {
	tmpDir := t.TempDir()
	w := ops.NewWriter(tmpDir)
	r := ops.NewReader(tmpDir)

	t1 := time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
	t2 := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
	t3 := time.Date(2026, 10, 3, 10, 0, 0, 0, time.UTC)

	u1 := ulid.MustNew(ulid.Timestamp(t1), ulid.Monotonic(strings.NewReader("entropy1entropy1"), 0)).String()
	u2 := ulid.MustNew(ulid.Timestamp(t2), ulid.Monotonic(strings.NewReader("entropy2entropy2"), 0)).String()
	u3 := ulid.MustNew(ulid.Timestamp(t3), ulid.Monotonic(strings.NewReader("entropy3entropy3"), 0)).String()

	b1 := ops.OpBatch{
		Version:   1,
		BatchID:   u1,
		CreatedAt: t1,
		Ops: []ops.Op{
			{Type: ops.OpAdd, EntryID: "inv-01", DossierScope: "s1", Fields: map[string]any{"text": "t1"}},
		},
	}
	b2 := ops.OpBatch{
		Version:   1,
		BatchID:   u2,
		CreatedAt: t2,
		Ops: []ops.Op{
			{Type: ops.OpAdd, EntryID: "inv-02", DossierScope: "s1", Fields: map[string]any{"text": "t2"}},
		},
	}
	b3 := ops.OpBatch{
		Version:   1,
		BatchID:   u3,
		CreatedAt: t3,
		Ops: []ops.Op{
			{Type: ops.OpAdd, EntryID: "inv-03", DossierScope: "s1", Fields: map[string]any{"text": "t3"}},
		},
	}

	for _, b := range []ops.OpBatch{b1, b2, b3} {
		if err := w.Write(b); err != nil {
			t.Fatalf("Write failed: %v", err)
		}
	}

	// Iterate after 1st: should return 2nd and 3rd
	var after1 []*ops.OpBatch
	for batch, err := range r.IterateAfter(context.Background(), u1) {
		if err != nil {
			t.Fatalf("IterateAfter error: %v", err)
		}
		after1 = append(after1, batch)
	}

	if len(after1) != 2 {
		t.Fatalf("expected 2 batches after u1, got %d", len(after1))
	}
	if after1[0].BatchID != u2 {
		t.Errorf("expected first returned to be %s, got %s", u2, after1[0].BatchID)
	}
	if after1[1].BatchID != u3 {
		t.Errorf("expected second returned to be %s, got %s", u3, after1[1].BatchID)
	}

	// Iterate after 2nd: should return only 3rd
	var after2 []*ops.OpBatch
	for batch, err := range r.IterateAfter(context.Background(), u2) {
		if err != nil {
			t.Fatalf("IterateAfter error: %v", err)
		}
		after2 = append(after2, batch)
	}
	if len(after2) != 1 || after2[0].BatchID != u3 {
		t.Fatalf("expected only u3 after u2, got %v", after2)
	}

	// Iterate after 3rd: should return none
	var after3 []*ops.OpBatch
	for batch, err := range r.IterateAfter(context.Background(), u3) {
		if err != nil {
			t.Fatalf("IterateAfter error: %v", err)
		}
		after3 = append(after3, batch)
	}
	if len(after3) != 0 {
		t.Fatalf("expected 0 batches after u3, got %d", len(after3))
	}
}

func TestReaderIterateBefore(t *testing.T) {
	t.Run("with custom resolver", func(t *testing.T) {
		tmpDir := t.TempDir()
		w := ops.NewWriter(tmpDir)
		r := ops.NewReader(tmpDir)

		t1 := time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
		t2 := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
		t3 := time.Date(2026, 10, 3, 10, 0, 0, 0, time.UTC)

		u1 := ulid.MustNew(ulid.Timestamp(t1), ulid.Monotonic(strings.NewReader("entropy1entropy1"), 0)).String()
		u2 := ulid.MustNew(ulid.Timestamp(t2), ulid.Monotonic(strings.NewReader("entropy2entropy2"), 0)).String()
		u3 := ulid.MustNew(ulid.Timestamp(t3), ulid.Monotonic(strings.NewReader("entropy3entropy3"), 0)).String()

		_ = w.Write(ops.OpBatch{Version: 1, BatchID: u1, CreatedAt: t1, Ops: []ops.Op{{Type: ops.OpAdd, EntryID: "e1", DossierScope: "s", Fields: map[string]any{"text": "t1"}}}})
		_ = w.Write(ops.OpBatch{Version: 1, BatchID: u2, CreatedAt: t2, Ops: []ops.Op{{Type: ops.OpAdd, EntryID: "e2", DossierScope: "s", Fields: map[string]any{"text": "t2"}}}})
		_ = w.Write(ops.OpBatch{Version: 1, BatchID: u3, CreatedAt: t3, Ops: []ops.Op{{Type: ops.OpAdd, EntryID: "e3", DossierScope: "s", Fields: map[string]any{"text": "t3"}}}})

		// Mock commit time between t2 and t3
		commitTime := time.Date(2026, 10, 2, 15, 0, 0, 0, time.UTC)
		r.SetCommitTimeResolver(func(ctx context.Context, commit string) (time.Time, error) {
			if commit == "commit-abc" {
				return commitTime, nil
			}
			return time.Time{}, os.ErrNotExist
		})

		var batches []*ops.OpBatch
		for batch, err := range r.IterateBefore(context.Background(), "commit-abc") {
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			batches = append(batches, batch)
		}

		if len(batches) != 2 {
			t.Fatalf("expected 2 batches before commitTime, got %d", len(batches))
		}
		if batches[0].BatchID != u1 || batches[1].BatchID != u2 {
			t.Errorf("unexpected batches returned: %v, %v", batches[0].BatchID, batches[1].BatchID)
		}
	})

	t.Run("with real git repo", func(t *testing.T) {
		repoDir := t.TempDir()
		opsDir := filepath.Join(repoDir, ".memory", "ops")

		// Init git repo
		runGit := func(args ...string) string {
			cmd := exec.Command("git", append([]string{"-C", repoDir}, args...)...)
			out, err := cmd.CombinedOutput()
			if err != nil {
				t.Fatalf("git %s failed: %v (output: %s)", strings.Join(args, " "), err, string(out))
			}
			return strings.TrimSpace(string(out))
		}

		runGit("init")
		runGit("config", "user.name", "Test Runner")
		runGit("config", "user.email", "test@example.com")
		runGit("commit", "--allow-empty", "-m", "First commit")
		commit1 := runGit("rev-parse", "HEAD")

		// Query commit timestamp
		c1TimeStr := runGit("log", "-1", "--format=%cI", commit1)
		c1Time, err := time.Parse(time.RFC3339, c1TimeStr)
		if err != nil {
			t.Fatalf("parse commit time: %v", err)
		}

		w := ops.NewWriter(opsDir)
		r := ops.NewReader(opsDir)

		// Create batch before commit and batch after commit
		tBefore := c1Time.Add(-10 * time.Minute)
		tAfter := c1Time.Add(10 * time.Minute)

		uBefore := ulid.MustNew(ulid.Timestamp(tBefore), ulid.Monotonic(strings.NewReader("entropy1entropy1"), 0)).String()
		uAfter := ulid.MustNew(ulid.Timestamp(tAfter), ulid.Monotonic(strings.NewReader("entropy2entropy2"), 0)).String()

		_ = w.Write(ops.OpBatch{Version: 1, BatchID: uBefore, CreatedAt: tBefore, Ops: []ops.Op{{Type: ops.OpAdd, EntryID: "e1", DossierScope: "s", Fields: map[string]any{"text": "t1"}}}})
		_ = w.Write(ops.OpBatch{Version: 1, BatchID: uAfter, CreatedAt: tAfter, Ops: []ops.Op{{Type: ops.OpAdd, EntryID: "e2", DossierScope: "s", Fields: map[string]any{"text": "t2"}}}})

		var batches []*ops.OpBatch
		for batch, err := range r.IterateBefore(context.Background(), commit1) {
			if err != nil {
				t.Fatalf("IterateBefore error: %v", err)
			}
			batches = append(batches, batch)
		}

		if len(batches) != 1 {
			t.Fatalf("expected 1 batch before commit1, got %d", len(batches))
		}
		if batches[0].BatchID != uBefore {
			t.Errorf("expected batch %s, got %s", uBefore, batches[0].BatchID)
		}
	})
}

func TestMigrateV1Events(t *testing.T) {
	tmpDir := t.TempDir()
	eventsDir := filepath.Join(tmpDir, "events")
	archiveDir := filepath.Join(tmpDir, "archive", "v1-events")

	// Create mock events dir with reviews and answers
	reviewsDir := filepath.Join(eventsDir, "reviews")
	if err := os.MkdirAll(reviewsDir, 0755); err != nil {
		t.Fatalf("mkdir reviews failed: %v", err)
	}

	testContent := `{"claim_id":"clm-1","state":"approved"}` + "\n"
	if err := os.WriteFile(filepath.Join(reviewsDir, "clm-1.jsonl"), []byte(testContent), 0644); err != nil {
		t.Fatalf("write mock event file failed: %v", err)
	}

	// Run migration
	if err := ops.MigrateV1Events(eventsDir, archiveDir); err != nil {
		t.Fatalf("MigrateV1Events failed: %v", err)
	}

	// Verify eventsDir is gone
	if _, err := os.Stat(eventsDir); !os.IsNotExist(err) {
		t.Fatalf("expected eventsDir %s to no longer exist", eventsDir)
	}

	// Verify archiveDir exists with file content
	migratedFile := filepath.Join(archiveDir, "reviews", "clm-1.jsonl")
	data, err := os.ReadFile(migratedFile)
	if err != nil {
		t.Fatalf("expected migrated file %s to exist: %v", migratedFile, err)
	}
	if string(data) != testContent {
		t.Fatalf("expected content %q, got %q", testContent, string(data))
	}

	// Running migration again when eventsDir doesn't exist should be a no-op
	if err := ops.MigrateV1Events(eventsDir, archiveDir); err != nil {
		t.Fatalf("MigrateV1Events second run failed: %v", err)
	}
}

